public class ArgReverserTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected [" + expected + "] but got [" + actual + "]");
            failures++;
        }
    }

    static String capture(String[] argv) {
        java.io.ByteArrayOutputStream buf = new java.io.ByteArrayOutputStream();
        java.io.PrintStream old = System.out;
        System.setOut(new java.io.PrintStream(buf));
        try {
            ArgReverser.main(argv);
        } finally {
            System.setOut(old);
        }
        return buf.toString().replace(System.lineSeparator(), "\n");
    }

    public static void main(String[] args) {
        check("one two three", "three two one\n", capture(new String[]{"one", "two", "three"}));
        check("no args prints empty line", "\n", capture(new String[0]));
        check("single arg", "solo\n", capture(new String[]{"solo"}));
        check("two args", "b a\n", capture(new String[]{"a", "b"}));
        check("numbers as text", "4 3 2 1\n", capture(new String[]{"1", "2", "3", "4"}));
        check("no trailing space", "end start\n", capture(new String[]{"start", "end"}));
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

