public class ArgReverser {

    public static void main(String[] args) {
        StringBuilder sb = new StringBuilder();
        for (int i = args.length - 1; i >= 0; i--) {
            sb.append(args[i]);
            if (i > 0) {
                sb.append(' ');
            }
        }
        System.out.println(sb.toString());
    }
}
